PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS departments(id INTEGER PRIMARY KEY AUTOINCREMENT, code TEXT NOT NULL UNIQUE, name TEXT NOT NULL, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS locations(id INTEGER PRIMARY KEY AUTOINCREMENT, department_id INTEGER NOT NULL, name TEXT NOT NULL, FOREIGN KEY(department_id) REFERENCES departments(id));
CREATE TABLE IF NOT EXISTS categories(id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY AUTOINCREMENT, username TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, full_name TEXT NOT NULL, role TEXT NOT NULL, department_id INTEGER, active INTEGER DEFAULT 1, created_at TEXT DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(department_id) REFERENCES departments(id));
CREATE TABLE IF NOT EXISTS assets(id INTEGER PRIMARY KEY AUTOINCREMENT, asset_code TEXT NOT NULL UNIQUE, name TEXT NOT NULL, category TEXT NOT NULL, model_serial TEXT, purchase_date TEXT, department TEXT NOT NULL, location TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'Đang sử dụng', unit TEXT DEFAULT 'Cái', price REAL DEFAULT 0, useful_life INTEGER DEFAULT 5, document_path TEXT, image_path TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP, updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS supplies(id INTEGER PRIMARY KEY AUTOINCREMENT, supply_code TEXT NOT NULL UNIQUE, name TEXT NOT NULL, unit TEXT NOT NULL, unit_price REAL DEFAULT 0, stock REAL DEFAULT 0, minimum_stock REAL DEFAULT 0);
CREATE TABLE IF NOT EXISTS stock_transactions(id INTEGER PRIMARY KEY AUTOINCREMENT, supply_id INTEGER NOT NULL, transaction_type TEXT NOT NULL, quantity REAL NOT NULL, note TEXT, user_id INTEGER, created_at TEXT DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(supply_id) REFERENCES supplies(id), FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS transfers(id INTEGER PRIMARY KEY AUTOINCREMENT, asset_id INTEGER NOT NULL, from_department TEXT NOT NULL, from_location TEXT NOT NULL, to_department TEXT NOT NULL, to_location TEXT NOT NULL, reason TEXT NOT NULL, transferred_at TEXT NOT NULL, created_by INTEGER, FOREIGN KEY(asset_id) REFERENCES assets(id), FOREIGN KEY(created_by) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS maintenance_tickets(id INTEGER PRIMARY KEY AUTOINCREMENT, asset_id INTEGER NOT NULL, repair_date TEXT NOT NULL, content TEXT NOT NULL, vendor TEXT, cost REAL DEFAULT 0, status TEXT NOT NULL, created_by INTEGER, created_at TEXT DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(asset_id) REFERENCES assets(id), FOREIGN KEY(created_by) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS maintenance_updates(id INTEGER PRIMARY KEY AUTOINCREMENT, ticket_id INTEGER NOT NULL, content TEXT NOT NULL, status TEXT NOT NULL, created_by INTEGER, created_at TEXT DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(ticket_id) REFERENCES maintenance_tickets(id));
CREATE TABLE IF NOT EXISTS inventory_sessions(id INTEGER PRIMARY KEY AUTOINCREMENT, title TEXT NOT NULL, scope TEXT NOT NULL, department_id INTEGER, status TEXT DEFAULT 'Đang kiểm kê', started_at TEXT DEFAULT CURRENT_TIMESTAMP, completed_at TEXT, created_by INTEGER);
CREATE TABLE IF NOT EXISTS inventory_items(id INTEGER PRIMARY KEY AUTOINCREMENT, session_id INTEGER NOT NULL, asset_id INTEGER NOT NULL, actual_status TEXT, actual_location TEXT, note TEXT, checked_at TEXT, FOREIGN KEY(session_id) REFERENCES inventory_sessions(id), FOREIGN KEY(asset_id) REFERENCES assets(id));
CREATE TABLE IF NOT EXISTS documents(id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, file_path TEXT NOT NULL, mime_type TEXT, asset_id INTEGER, uploaded_by INTEGER, created_at TEXT DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(asset_id) REFERENCES assets(id));
CREATE TABLE IF NOT EXISTS audit_logs(id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, username TEXT, actor_name TEXT, action TEXT NOT NULL, object_type TEXT, object_id TEXT, detail TEXT, ip_address TEXT, previous_hash TEXT, entry_hash TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS asset_custodians(id INTEGER PRIMARY KEY AUTOINCREMENT, asset_id INTEGER NOT NULL, custodian_name TEXT NOT NULL, manager_name TEXT, assigned_at TEXT NOT NULL, returned_at TEXT, FOREIGN KEY(asset_id) REFERENCES assets(id));
CREATE TABLE IF NOT EXISTS approval_requests(id INTEGER PRIMARY KEY AUTOINCREMENT, request_code TEXT UNIQUE NOT NULL, request_type TEXT NOT NULL, title TEXT NOT NULL, requester TEXT NOT NULL, amount REAL DEFAULT 0, current_step INTEGER DEFAULT 1, status TEXT NOT NULL, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS approval_actions(id INTEGER PRIMARY KEY AUTOINCREMENT, request_id INTEGER NOT NULL, actor TEXT NOT NULL, action TEXT NOT NULL, reason TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(request_id) REFERENCES approval_requests(id));
CREATE TABLE IF NOT EXISTS electronic_documents(id INTEGER PRIMARY KEY AUTOINCREMENT, document_code TEXT UNIQUE NOT NULL, document_type TEXT NOT NULL, asset_id INTEGER, content TEXT, status TEXT NOT NULL, created_at TEXT DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(asset_id) REFERENCES assets(id));
CREATE TABLE IF NOT EXISTS electronic_signatures(id INTEGER PRIMARY KEY AUTOINCREMENT, document_id INTEGER NOT NULL, signer TEXT NOT NULL, signature_hash TEXT NOT NULL, signed_at TEXT DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(document_id) REFERENCES electronic_documents(id));
CREATE TABLE IF NOT EXISTS vendors(id INTEGER PRIMARY KEY AUTOINCREMENT, vendor_code TEXT UNIQUE NOT NULL, name TEXT NOT NULL, tax_code TEXT, contact TEXT, phone TEXT, rating REAL DEFAULT 0);
CREATE TABLE IF NOT EXISTS purchase_orders(id INTEGER PRIMARY KEY AUTOINCREMENT, po_code TEXT UNIQUE NOT NULL, vendor_id INTEGER NOT NULL, item TEXT NOT NULL, quantity REAL NOT NULL, total REAL DEFAULT 0, status TEXT NOT NULL, order_date TEXT NOT NULL, FOREIGN KEY(vendor_id) REFERENCES vendors(id));
CREATE TABLE IF NOT EXISTS asset_lifecycle(id INTEGER PRIMARY KEY AUTOINCREMENT, asset_id INTEGER NOT NULL, event_type TEXT NOT NULL, detail TEXT, actor TEXT, event_time TEXT DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(asset_id) REFERENCES assets(id));
CREATE TABLE IF NOT EXISTS it_asset_details(id INTEGER PRIMARY KEY AUTOINCREMENT, asset_id INTEGER NOT NULL UNIQUE, hostname TEXT, ip_address TEXT, mac_address TEXT, operating_system TEXT, cpu TEXT, ram TEXT, storage TEXT, license_info TEXT, security_status TEXT, FOREIGN KEY(asset_id) REFERENCES assets(id));
CREATE TABLE IF NOT EXISTS disposal_records(id INTEGER PRIMARY KEY AUTOINCREMENT, disposal_code TEXT UNIQUE NOT NULL, asset_id INTEGER NOT NULL, reason TEXT NOT NULL, book_value REAL DEFAULT 0, sale_price REAL DEFAULT 0, disposal_method TEXT, data_wiped INTEGER DEFAULT 0, status TEXT NOT NULL, created_at TEXT DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(asset_id) REFERENCES assets(id));
CREATE INDEX IF NOT EXISTS idx_assets_status ON assets(status); CREATE INDEX IF NOT EXISTS idx_assets_department ON assets(department); CREATE INDEX IF NOT EXISTS idx_audit_created ON audit_logs(created_at);
